<?php
namespace App\Http\Controllers\ClientControl;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Illuminate\Support\Facades\Storage;
use Illuminate\Validation\ValidationException;
class ClientDrawingAdminController extends Controller {
 private function check(Request $r,string $action,?int $project=null): void {
  $u=$r->user('web'); abort_unless($u && $u->isActive() && $u->hasPermission('client_control.drawings.view') && $u->hasPermission('client_control.drawings.'.$action),403);
  if($project!==null) abort_unless($u->hasProjectAccess($project),403);
 }
 private function projects(Request $r) { return DB::table('projects')->orderBy('project_name')->get()->filter(fn($p)=>$r->user('web')->hasProjectAccess((int)$p->id)); }
 private function drawing(Request $r,int $id,string $action) { $this->check($r,$action); $d=DB::table('client_drawings')->where('id',$id)->first(); abort_unless($d,404); $this->check($r,$action,(int)$d->project_id); return $d; }
 private function masters(): array { return ['categories'=>DB::table('client_drawing_categories')->orderBy('sort_order')->get(),'types'=>DB::table('client_drawing_types')->orderBy('sort_order')->get(),'purposes'=>DB::table('client_drawing_purposes')->orderBy('sort_order')->get()]; }
 private function latest(int $id) { return DB::table('client_drawing_revisions')->where('drawing_id',$id)->orderByDesc('revision'); }
 private function data(Request $r): array { $rules=['title'=>'required|string|max:255','revision_reference'=>'required|string|max:50','purpose_id'=>['required',Rule::exists('client_drawing_purposes','id')->where('is_active',1)],'drawing_date'=>'required|date']; foreach(['consultant_reference','block','floor','location','consultant','scale','sheet_number'] as $f) $rules[$f]='nullable|string|max:255'; foreach(['client_description','internal_remarks'] as $f) $rules[$f]='nullable|string|max:10000'; $rules += ['client_approval_required'=>'required|boolean','client_download_allowed'=>'required|boolean','client_approval_due_date'=>'nullable|date','revision_description'=>'nullable|string|max:10000']; $data=$r->validate($rules); if(!$data['client_approval_required']) $data['client_approval_due_date']=null; return $data; }
 private function event(Request $r,int $id,int $rev,string $action,array $details): void { DB::table('client_drawing_events')->insert(['drawing_id'=>$id,'revision_id'=>$rev,'actor_guard'=>'web','actor_id'=>$r->user('web')->id,'action'=>$action,'details'=>json_encode($details,JSON_THROW_ON_ERROR),'ip_address'=>$r->ip(),'created_at'=>now()]); }
 public function index(Request $r) { $this->check($r,'view'); $projects=$this->projects($r); $f=$r->validate(['project_id'=>'nullable|integer','category_id'=>'nullable|integer','type_id'=>'nullable|integer','floor'=>'nullable|string|max:255','status'=>'nullable|string|max:30','q'=>'nullable|string|max:255']); $latest=DB::table('client_drawing_revisions')->selectRaw('drawing_id, MAX(revision) as latest_revision')->groupBy('drawing_id'); $q=DB::table('client_drawings as d')->joinSub($latest,'l',fn($j)=>$j->on('d.id','=','l.drawing_id'))->join('client_drawing_revisions as r',fn($j)=>$j->on('r.drawing_id','=','d.id')->on('r.revision','=','l.latest_revision'))->join('projects as p','p.id','=','d.project_id')->join('client_drawing_categories as c','c.id','=','d.category_id')->whereIn('d.project_id',$projects->pluck('id')->all())->whereNull('d.archived_at'); foreach(['project_id'=>'d.project_id','category_id'=>'d.category_id','type_id'=>'d.type_id','floor'=>'r.floor','status'=>'r.status'] as $k=>$col) if(!empty($f[$k])) $q->where($col,$f[$k]); if(!empty($f['q'])) $q->where(fn($x)=>$x->where('r.title','like','%'.$f['q'].'%')->orWhere('d.drawing_number','like','%'.$f['q'].'%')); $drawings=$q->select('d.*','r.id as latest_revision_id','r.title','r.status','r.revision_reference','r.floor','p.project_name','c.name as category_name')->orderByDesc('d.id')->paginate(25)->withQueryString();  $thumbFiles=DB::table('client_drawing_files')->whereIn('revision_id',$drawings->getCollection()->pluck('latest_revision_id'))->whereIn('mime_type',['image/jpeg','image/png','application/pdf'])->get()->groupBy('revision_id'); return view('client-control.admin.drawings.index',compact('projects','drawings','thumbFiles')+$this->masters()); }
 public function create(Request $r) { $this->check($r,'create'); return view('client-control.admin.drawings.form',['projects'=>$this->projects($r),'drawing'=>null,'revision'=>null,'revising'=>false]+$this->masters()); }
 public function store(Request $r) { $this->check($r,'create'); $keys=$r->validate(['project_id'=>'required|integer|exists:projects,id','category_id'=>'required|integer','type_id'=>'required|integer']); $this->check($r,'create',(int)$keys['project_id']); $data=$this->data($r); if($data['client_download_allowed']) $this->check($r,'manage_client_downloads'); $this->check($r,'upload',(int)$keys['project_id']); $uploads=$this->prepareFiles($r,true); try { $id=DB::transaction(function() use($r,$keys,$data,$uploads){ $cat=DB::table('client_drawing_categories')->where('id',$keys['category_id'])->lockForUpdate()->first(); abort_unless($cat && $cat->is_active,422); abort_unless(DB::table('client_drawing_types')->where('id',$keys['type_id'])->where('category_id',$cat->id)->where('is_active',1)->lockForUpdate()->first(),422); $seq=DB::table('client_drawing_sequences')->where('category_id',$cat->id); $row=$seq->lockForUpdate()->first(); $n=($row->last_number??0)+1; if($row) $seq->update(['last_number'=>$n,'updated_at'=>now()]); else DB::table('client_drawing_sequences')->insert(['category_id'=>$cat->id,'last_number'=>$n,'created_at'=>now(),'updated_at'=>now()]); $id=DB::table('client_drawings')->insertGetId($keys+['drawing_number'=>'RH-DRW-'.$cat->code.'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT),'created_by'=>$r->user('web')->id,'created_at'=>now(),'updated_at'=>now()]); $rev=DB::table('client_drawing_revisions')->insertGetId($data+['drawing_id'=>$id,'revision'=>0,'status'=>'Draft','uploaded_by'=>$r->user('web')->id,'created_at'=>now(),'updated_at'=>now()]); $this->attach($r,$rev,$uploads); $this->event($r,$id,$rev,'draft_created',$data); return $id; },3); } catch (\Throwable $e) { $this->cleanup($uploads); throw $e; } return redirect()->route('client-control.admin.drawings.show',$id)->with('success','Drawing uploaded as draft.'); }
 public function show(Request $r,int $drawing) { $d=$this->drawing($r,$drawing,'view'); $revisions=$this->latest($drawing)->get(); $events=$r->user('web')->hasPermission('client_control.drawings.audit')?DB::table('client_drawing_events')->where('drawing_id',$drawing)->orderByDesc('id')->paginate(20):null; return view('client-control.admin.drawings.show',['drawing'=>$d,'revisions'=>$revisions,'responses'=>DB::table('client_drawing_responses as a')->join('client_drawing_publications as p','p.id','=','a.publication_id')->join('client_drawing_revisions as v','v.id','=','p.revision_id')->join('client_users as c','c.id','=','a.client_user_id')->where('p.drawing_id',$drawing)->select('a.*','v.revision_reference','c.name as client_name','p.active_drawing_id')->orderByDesc('a.responded_at')->get(),'events'=>$events,'publication'=>DB::table('client_drawing_publications')->where('active_drawing_id',$drawing)->first(),'purpose'=>DB::table('client_drawing_purposes')->where('id',$revisions->first()?->purpose_id)->value('name'),'actors'=>DB::table('users')->whereIn('id',$events ? $events->getCollection()->where('actor_guard','web')->pluck('actor_id') : [])->pluck('name','id'),'files'=>DB::table('client_drawing_files')->whereIn('revision_id',$revisions->pluck('id'))->get()->groupBy('revision_id'),'project'=>DB::table('projects')->where('id',$d->project_id)->first()]); }
 public function edit(Request $r,int $drawing) { $d=$this->drawing($r,$drawing,'update'); $rev=$this->latest($drawing)->first(); abort_unless(!$d->archived_at && $rev && $rev->status==='Draft',409); return view('client-control.admin.drawings.form',['drawing'=>$d,'revision'=>$rev,'projects'=>$this->projects($r),'revising'=>false]+$this->masters()); }
 public function update(Request $r,int $drawing) { $this->drawing($r,$drawing,'update'); $data=$this->data($r); if($data['client_download_allowed']) $this->check($r,'manage_client_downloads'); DB::transaction(function() use($r,$drawing,$data){ $d=DB::table('client_drawings')->where('id',$drawing)->lockForUpdate()->first(); abort_unless($d && !$d->archived_at,409); $rev=$this->latest($drawing)->lockForUpdate()->first(); abort_unless($rev && $rev->status==='Draft',409); abort_if(DB::table('client_drawing_revisions')->where('drawing_id',$drawing)->where('id','!=',$rev->id)->where('revision_reference',$data['revision_reference'])->exists(),422); DB::table('client_drawing_revisions')->where('id',$rev->id)->update($data+['updated_at'=>now()]); $this->event($r,$drawing,$rev->id,'draft_updated',['before'=>(array)$rev,'after'=>$data]); }); return redirect()->route('client-control.admin.drawings.show',$drawing)->with('success','Draft updated.'); }

 public function locations(Request $r,int $project) {
  $this->check($r,'view',$project); $result=[];
  foreach(['blocks'=>['project_blocks',['id','name']], 'floors'=>['project_floors',['id','name','project_block_id']], 'units'=>['project_units',['id','name','project_block_id','project_floor_id']], 'rooms'=>['project_rooms',['id','name','project_block_id','project_floor_id','project_unit_id']], 'subspaces'=>['project_subspaces',['id','name','project_block_id','project_floor_id','project_unit_id','project_room_id']]] as $key=>[$table,$cols]) $result[$key]=DB::table($table)->where('project_id',$project)->where('is_active',1)->orderBy('name')->get($cols);
  return response()->json($result);
 }
 private function prepareFiles(Request $r,bool $required): array {
  $r->validate(['file'=>($required?'required':'nullable').'|file|max:51200','preview'=>'nullable|file|max:51200']);
  $result=[]; try { foreach(['file'=>'original','preview'=>'preview'] as $field=>$kind) {
   if(!$r->hasFile($field)) continue; $f=$r->file($field); $ext=strtolower($f->getClientOriginalExtension()); $head=file_get_contents($f->getRealPath(),false,null,0,4096);
   $valid=match($ext){'pdf'=>str_starts_with($head,'%PDF-'),'jpg','jpeg'=>str_starts_with($head,"\xFF\xD8\xFF") && @getimagesize($f->getRealPath())!==false,'png'=>str_starts_with($head,"\x89PNG\r\n\x1a\n") && @getimagesize($f->getRealPath())!==false,'dwg'=>preg_match('/^AC10[0-9]{2}/',$head)===1,'dxf'=>str_starts_with($head,'AutoCAD Binary DXF') || preg_match('/^\s*0\s+SECTION\s+/i',$head)===1,default=>false};
   if(!$valid || ($kind==='preview' && $ext!=='pdf')) throw ValidationException::withMessages([$field=>'Invalid drawing format or file signature.']);
   $path=$f->storeAs('client-drawings', (string)\Illuminate\Support\Str::uuid().'.'.$ext,'local'); if(!$path) throw new \RuntimeException('Private file storage failed.');
   $result[]=['kind'=>$kind,'original_filename'=>mb_substr(basename(str_replace('\\','/',$f->getClientOriginalName())),0,255),'disk'=>'local','storage_path'=>$path,'mime_type'=>match($ext){'pdf'=>'application/pdf','jpg','jpeg'=>'image/jpeg','png'=>'image/png',default=>'application/octet-stream'},'file_size'=>$f->getSize(),'sha256'=>hash_file('sha256',$f->getRealPath())];
  } return $result; } catch(\Throwable $e){$this->cleanup($result);throw $e;}
 }
 private function cleanup(array $files): void { foreach($files as $f) Storage::disk('local')->delete($f['storage_path']); }
 private function attach(Request $r,int $rev,array $files): void { foreach($files as $f) DB::table('client_drawing_files')->insert($f+['revision_id'=>$rev,'uploaded_by'=>$r->user('web')->id,'created_at'=>now(),'updated_at'=>now()]); }
 public function upload(Request $r,int $drawing) {
  $this->drawing($r,$drawing,'upload'); $files=$this->prepareFiles($r,true);
  try { DB::transaction(function()use($r,$drawing,$files){$d=DB::table('client_drawings')->where('id',$drawing)->lockForUpdate()->first();$rev=$this->latest($drawing)->lockForUpdate()->first();abort_unless(!$d->archived_at && $rev && $rev->status==='Draft' && !DB::table('client_drawing_files')->where('revision_id',$rev->id)->exists(),409);$this->attach($r,$rev->id,$files);$this->event($r,$drawing,$rev->id,'files_uploaded',[]);}); } catch(\Throwable $e){$this->cleanup($files);throw $e;} return back()->with('success','Files uploaded.');
 }
 public function revise(Request $r,int $drawing) {
  $d=$this->drawing($r,$drawing,'revise');$this->check($r,'upload',$d->project_id);$rev=$this->latest($drawing)->first();abort_unless(!$d->archived_at && $rev,409);$rev->revision_reference='R'.str_pad((string)($rev->revision+1),2,'0',STR_PAD_LEFT);$rev->drawing_date=now()->toDateString();$rev->revision_description=null;return view('client-control.admin.drawings.form',['drawing'=>$d,'revision'=>$rev,'projects'=>$this->projects($r),'revising'=>true]+$this->masters());
 }
 public function storeRevision(Request $r,int $drawing) {
  $d=$this->drawing($r,$drawing,'revise');$this->check($r,'upload',$d->project_id);$data=$this->data($r); if($data['client_download_allowed']) $this->check($r,'manage_client_downloads');$r->validate(['revision_description'=>'required|string|max:10000','base_revision'=>'required|integer']);$files=$this->prepareFiles($r,true);
  try {DB::transaction(function()use($r,$drawing,$data,$files){$d=DB::table('client_drawings')->where('id',$drawing)->lockForUpdate()->first();$old=$this->latest($drawing)->lockForUpdate()->first();abort_unless(!$d->archived_at && $old && $old->id==(int)$r->base_revision,409);abort_if(DB::table('client_drawing_revisions')->where('drawing_id',$drawing)->where('revision_reference',$data['revision_reference'])->exists(),422,'Revision reference already exists.');$rev=DB::table('client_drawing_revisions')->insertGetId($data+['drawing_id'=>$drawing,'revision'=>$old->revision+1,'status'=>'Draft','uploaded_by'=>$r->user('web')->id,'created_at'=>now(),'updated_at'=>now()]);$this->attach($r,$rev,$files);$this->event($r,$drawing,$rev,'revision_created',$data);});}catch(\Throwable $e){$this->cleanup($files);throw $e;}return redirect()->route('client-control.admin.drawings.show',$drawing)->with('success','New draft revision uploaded.');
 }
 public function download(Request $r,int $drawing,int $file) {
  $this->drawing($r,$drawing,'download');$f=DB::table('client_drawing_files as f')->join('client_drawing_revisions as r','r.id','=','f.revision_id')->where('r.drawing_id',$drawing)->where('f.id',$file)->select('f.*')->first();abort_unless($f && $f->disk==='local' && Storage::disk('local')->exists($f->storage_path),404);$this->event($r,$drawing,$f->revision_id,'file_downloaded',['file_id'=>$file]);return Storage::disk('local')->download($f->storage_path,$f->original_filename,['Content-Type'=>'application/octet-stream','X-Content-Type-Options'=>'nosniff','Cache-Control'=>'private, no-store']);
 }

 public function workflow(Request $r,int $drawing,int $revision,string $action) {
  $permissions=['submit'=>'submit','authorize'=>'approve','return'=>'reject','publish'=>'publish','withdraw'=>'withdraw'];
  abort_unless(isset($permissions[$action]),404); $this->drawing($r,$drawing,$permissions[$action]);
  $r->validate(['notes'=>'nullable|string|max:10000']);
  DB::transaction(function() use($r,$drawing,$revision,$action){
   $d=DB::table('client_drawings')->where('id',$drawing)->lockForUpdate()->first(); abort_unless($d && !$d->archived_at,409);
   $q=DB::table('client_drawing_revisions')->where('drawing_id',$drawing)->where('id',$revision); $v=$q->lockForUpdate()->first(); abort_unless($v,404);
   $active=DB::table('client_drawing_publications')->where('active_drawing_id',$drawing)->lockForUpdate()->first();
   $uid=$r->user('web')->id; $now=now();
   if($action==='withdraw') { abort_unless($active && $active->revision_id==$revision,409); DB::table('client_drawing_publications')->where('id',$active->id)->update(['active_drawing_id'=>null,'ended_at'=>$now,'ended_by'=>$uid,'end_reason'=>'Withdrawn','end_notes'=>$r->notes,'updated_at'=>$now]); $q->update(['status'=>'Withdrawn','updated_at'=>$now]); }
   else {
    abort_unless($this->latest($drawing)->first()->id==$revision,409,'Only the latest revision may be processed.');
    $files=DB::table('client_drawing_files')->where('revision_id',$revision)->get();
    if(in_array($action,['submit','authorize','publish'])) { abort_unless($files->contains('kind','original'),422,'Upload an original drawing first.'); foreach($files as $f) abort_unless($f->disk==='local' && Storage::disk('local')->exists($f->storage_path),422,'Drawing file missing.'); }
    if($action==='submit'){abort_unless($v->status==='Draft',409);$q->update(['status'=>'Submitted','submitted_at'=>$now,'submitted_by'=>$uid,'updated_at'=>$now]);}
    if($action==='authorize'){abort_unless($v->status==='Submitted',409);$q->update(['status'=>'Approved','approved_at'=>$now,'approved_by'=>$uid,'updated_at'=>$now]);}
    if($action==='return'){abort_unless(in_array($v->status,['Submitted','Approved']),409);$r->validate(['notes'=>'required|string|max:10000']);$q->update(['status'=>'Draft','review_notes'=>$r->notes,'returned_at'=>$now,'returned_by'=>$uid,'approved_at'=>null,'approved_by'=>null,'submitted_at'=>null,'submitted_by'=>null,'updated_at'=>$now]);}
    if($action==='publish'){
     abort_unless($v->status==='Approved' && $v->approved_at,409);
     $original=$files->firstWhere('kind','original'); abort_unless(in_array($original->mime_type,['application/pdf','image/jpeg','image/png']) || $files->contains(fn($f)=>$f->kind==='preview' && $f->mime_type==='application/pdf'),422,'CAD drawings require a PDF preview before publication.');
     if($active){DB::table('client_drawing_publications')->where('id',$active->id)->update(['active_drawing_id'=>null,'ended_at'=>$now,'ended_by'=>$uid,'end_reason'=>'Superseded','updated_at'=>$now]);DB::table('client_drawing_revisions')->where('id',$active->revision_id)->where('drawing_id',$drawing)->update(['status'=>'Superseded','updated_at'=>$now]);}
     $snapshot=['drawing_number'=>$d->drawing_number,'category'=>DB::table('client_drawing_categories')->where('id',$d->category_id)->value('name'),'type'=>DB::table('client_drawing_types')->where('id',$d->type_id)->value('name'),'purpose'=>DB::table('client_drawing_purposes')->where('id',$v->purpose_id)->value('name')]; foreach(['title','revision_reference','drawing_date','block','floor','location','client_description'] as $key) $snapshot[$key]=$v->$key;
     DB::table('client_drawing_publications')->insert(['drawing_id'=>$drawing,'revision_id'=>$revision,'active_drawing_id'=>$drawing,'snapshot'=>json_encode($snapshot,JSON_THROW_ON_ERROR),'client_download_allowed'=>$v->client_download_allowed,'client_approval_required'=>$v->client_approval_required,'client_approval_due_date'=>$v->client_approval_due_date,'published_by'=>$uid,'published_at'=>$now,'created_at'=>$now,'updated_at'=>$now]);$q->update(['status'=>'Published','updated_at'=>$now]);
    }
   } $this->event($r,$drawing,$revision,$action,['notes'=>$r->notes]);
  }); return redirect()->route('client-control.admin.drawings.show',$drawing)->with('success','Drawing action completed: '.$action);
 }
 public function preview(Request $r,int $drawing,int $file) {
  $this->drawing($r,$drawing,'view');$f=DB::table('client_drawing_files as f')->join('client_drawing_revisions as r','r.id','=','f.revision_id')->where('r.drawing_id',$drawing)->where('f.id',$file)->select('f.*')->first();abort_unless($f && $f->disk==='local' && in_array($f->mime_type,['application/pdf','image/jpeg','image/png']) && Storage::disk('local')->exists($f->storage_path),404);if($r->query('thumbnail')==='1') return \App\Services\ClientControl\DrawingThumbnail::response($f);$this->event($r,$drawing,$f->revision_id,'file_previewed',['file_id'=>$file]);return Storage::disk('local')->response($f->storage_path,$f->original_filename,['Content-Type'=>$f->mime_type,'X-Content-Type-Options'=>'nosniff','Cache-Control'=>'private, no-store'],'inline');
 }
}
